package com.gomgomapps.math.core;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class NamibiaGeometricPatternsTest {
 private String drawing(int n,int count,int offset){StringJoiner out=new StringJoiner(",");for(int slot=offset;slot<offset+count;slot++)for(int edge=0;edge<n;edge++)out.add(slot+":"+edge);return out.toString();}
 private List<String> answers(int n,int t){return new ArrayList<>(List.of(drawing(n,t,0),""+(5*n),""+(6*n),""+(7*n),"2",""+n));}
 @Test public void drawingAndSameTableAndVerbalRuleAreAllRequiredFromPublicGivens(){for(int n=3;n<=6;n++)for(int t=4;t<=7;t++){Question q=GeometricMultiplePatterns.make(n,t);assertNotNull(GeometricMultiplePatterns.read(q));Arrays.fill(q.answers,"poison");q.expression="poison";List<String> a=answers(n,t);assertTrue(new Checker().check(q,List.of(),a).correct());a.set(0,"");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),a).status);a=answers(n,t);a.set(0,drawing(n,t-1,0));assertEquals(0,new Checker().check(q,List.of(),a).index);a=answers(n,t);a.set(1,"1");assertEquals(1,new Checker().check(q,List.of(),a).index);a=answers(n,t);a.set(4,"0");assertEquals(4,new Checker().check(q,List.of(),a).index);a=answers(n,t);a.set(5,"1");assertEquals(5,new Checker().check(q,List.of(),a).index);}}
 @Test public void everyPolygonMustBeClosedButItsPositionAndDrawingOrderAreFree(){for(int n=3;n<=6;n++){Question q=GeometricMultiplePatterns.make(n,4);List<String> a=answers(n,4);List<String> tokens=new ArrayList<>(List.of(drawing(n,4,3).split(",")));Collections.reverse(tokens);a.set(0,String.join(",",tokens));assertTrue(new Checker().check(q,List.of(),a).correct());a.set(0,drawing(n,4,0)+",6:0");assertEquals(0,new Checker().check(q,List.of(),a).index);a.set(0,drawing(n,5,0));assertEquals(0,new Checker().check(q,List.of(),a).index);assertNull(GeometricMultiplePatterns.edges("7:0",n));assertNull(GeometricMultiplePatterns.edges("0:0,0:0",n));assertNull(GeometricMultiplePatterns.edges("0:"+n,n));}}
 @Test public void normalNaSixPlacementsHelpAndMalformedInputsStayWithinTheirContracts(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(GeometricMultiplePatterns.ID,6));Generator gen=new Generator(new Random(299));List<String> recent=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<16;i++){Question q=gen.next(GeometricMultiplePatterns.ID,recent,false,GlobalCurriculum.limits(pack.id,GeometricMultiplePatterns.ID,6));assertNotNull(GeometricMultiplePatterns.read(q));assertTrue(seen.add(q.signature()));recent.add(q.signature());}assertFalse(Curriculum.inCurriculum(GeometricMultiplePatterns.SKILL,2022));Question q=GeometricMultiplePatterns.make(4,4);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(8,h.size());assertFalse(h.canTransfer());List<String> input=List.of("4","4","16","20","24","28","2","4");for(int i=0;i<8;i++)assertTrue(h.step(i).accepts(input.get(i)));q.prompt=q.prompt.replace("4 | 8 | 12 | 16","4 | 8 | 13 | 16");assertNull(GeometricMultiplePatterns.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),answers(4,4)).status);}
}
